/* Hashtiva workspace: coherent local demo workflows, no external services. */
const fa=n=>Number(n).toLocaleString('fa-IR');
paths.spark='M12 2l3 7 7 3-7 3-3 7-3-7-7-3 7-3z';paths.box='m3 7 9-5 9 5v10l-9 5-9-5z M3 7l9 5 9-5M12 12v10M7 4l9 5';paths.book='M3 4h6a4 4 0 0 1 3 2 4 4 0 0 1 3-2h6v16h-6a4 4 0 0 0-3 2 4 4 0 0 0-3-2H3z M12 6v16';paths.search='M16 10a6 6 0 1 1-12 0 6 6 0 0 1 12 0m-2 5 7 7';paths.check='m5 12 4 4L19 6';paths.arrow='m14 6-6 6 6 6';paths.settings='M12 8a4 4 0 1 1 0 8 4 4 0 0 1 0-8 M12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2';
let tabFilter='all',selectedInbox=0,inboxFilter='all',postFilter='all';let salesTab='orders';
const messagesState=readLocal('ht-inbox-v3',[{name:'سارا محمدی',network:'instagram',subject:'راهنمای انتخاب محصول',text:'سلام، این محصول برای هدیه مناسبه؟ بسته‌بندی هم داره؟',state:'open',time:'۵ دقیقه پیش',tag:'سؤال محصول',replies:[]},{name:'آرمان رضایی',network:'whatsapp',subject:'پیگیری سفارش',text:'سلام، سفارش من چه زمانی ارسال می‌شه؟',state:'open',time:'۱۲ دقیقه پیش',tag:'پیگیری سفارش',replies:[]},{name:'نگار احمدی',network:'telegram',subject:'همکاری با برند',text:'برای همکاری و معرفی محصولات چطور با شما در ارتباط باشم؟',state:'human',time:'۲۸ دقیقه پیش',tag:'همکاری',replies:[]}]);
let knowledge=readLocal('ht-knowledge',[{title:'شرایط ارسال',text:'ارسال سفارش‌ها پس از تأیید، در ۲ تا ۳ روز کاری انجام می‌شود.'},{title:'بسته‌بندی هدیه',text:'بسته‌بندی هدیه برای محصولات منتخب در دسترس است؛ پیش از ثبت سفارش، موجودی آن را بپرسید.'}]);let flows=readLocal('ht-flows',[{title:'از کامنت تا گفتگو',trigger:'قیمت',text:'سلام! ممنون از توجه شما. برای کدام محصول راهنمایی می‌خواهید؟',active:true},{title:'پاسخ به سؤال‌های ارسال',trigger:'ارسال',text:'ارسال سفارش‌ها پس از تأیید در ۲ تا ۳ روز کاری انجام می‌شود.',active:true},{title:'درخواست صحبت با تیم',trigger:'پشتیبانی',text:'درخواست شما برای بررسی به تیم ارجاع داده شد.',active:false}]);
let products=readLocal('ht-products',[{name:'ست هدیه مینیمال',price:'۸۹۰٬۰۰۰',stock:24},{name:'دفتر برنامه‌ریزی روزانه',price:'۲۴۰٬۰۰۰',stock:42},{name:'ماگ سرامیکی',price:'۳۲۰٬۰۰۰',stock:18}]);let orders=readLocal('ht-orders',[{id:1042,name:'سارا محمدی',product:'ست هدیه مینیمال',network:'instagram',value:'۸۹۰٬۰۰۰',state:'در انتظار بررسی'},{id:1041,name:'آرمان رضایی',product:'دفتر برنامه‌ریزی روزانه',network:'whatsapp',value:'۲۴۰٬۰۰۰',state:'آماده ارسال'},{id:1040,name:'نگار احمدی',product:'ماگ سرامیکی',network:'telegram',value:'۳۲۰٬۰۰۰',state:'ارسال شده'}]);
function saveV3(){localStorage.setItem('ht-inbox-v3',JSON.stringify(messagesState));localStorage.setItem('ht-knowledge',JSON.stringify(knowledge));localStorage.setItem('ht-flows',JSON.stringify(flows));localStorage.setItem('ht-products',JSON.stringify(products));localStorage.setItem('ht-orders',JSON.stringify(orders))}
const titles={dashboard:'نمای کلی',studio:'محتوا و انتشار',calendar:'تقویم انتشار',inbox:'صندوق گفتگو',automations:'جریان‌های خودکار',knowledge:'آموزش دستیار',sales:'محصولات و سفارش‌ها',growth:'فرصت‌های رشد',analytics:'گزارش عملکرد',channels:'حساب‌های اجتماعی',audience:'مخاطبان',settings:'تنظیمات فضای کار',plans:'اشتراک و مصرف',help:'راهنمای هشتیوا'};
pages.push(['knowledge','آموزش دستیار','book'],['sales','محصولات و سفارش‌ها','box']);contexts.knowledge=['آموزش دستیار','دستیار به چه اطلاعاتی نیاز دارد؟','اطلاعات محصول، شرایط ارسال و پرسش‌های پرتکرار را ثبت کنید. برای سؤال‌های خارج از این منابع، ارجاع به تیم را انتخاب کنید.'];contexts.sales=['دستیار فروش','چطور فروش را پیگیری کنم؟','ابتدا سفارش‌های در انتظار بررسی را باز کنید. جزئیات و موجودی محصول را تأیید کنید و پس از تأیید پرداخت واقعی، وضعیت ارسال را تغییر دهید.'];
function navV3(){const groups=[['میز کار',[['dashboard','home'],['inbox','inbox'],['studio','camera'],['calendar','calendar']]],['دستیار و رشد',[['automations','flow'],['knowledge','spark'],['growth','chart']]],['کسب‌وکار',[['sales','box'],['audience','users'],['analytics','chart'],['channels','flow']]]];nav.innerHTML=groups.map(([label,items])=>`<div class="nav-group-label">${label}</div>${items.map(([id,ic])=>`<button class="nav-item ${current===id?'active':''}" data-page="${id}">${icon(ic)}<span>${titles[id]}</span>${id==='inbox'?`<span class="badge">${fa(messagesState.filter(m=>m.state!=='done').length)}</span>`:id==='knowledge'?'<span class="subtle-ai"><img class="octopus-inline" src="assets/octopus.svg" alt="هوش مصنوعی"></span>':''}</button>`).join('')}`).join('')}
document.querySelector('.workspace').innerHTML='<span class="workspace-mark">H</span><div><b>استودیو هشتیوا</b><small>فضای کاری نمونه</small></div><span>⌄</span>';
document.querySelector('.side-bottom').innerHTML=`<button class="sidebar-ai" data-page="knowledge">${icon('spark')}<div><b>دستیار برند شما</b><small>منابع دانش و تنظیم رفتار</small></div>${icon('arrow')}</button><button class="nav-item" data-page="settings">${icon('settings')}<span>تنظیمات</span></button><button class="nav-item" data-page="help">${icon('book')}<span>راهنما</span></button><div class="profile"><span class="avatar">م</span><div><b>مدیر فضای کار</b><small>پیش‌نمایش محصول</small></div><span class="online"></span></div>`;
document.querySelector('.header-right').innerHTML=`<button id="menu" class="icon-button" aria-label="نمایش منو">☰</button><span class="crumb">استودیو هشتیوا <span>/</span><b id="crumb">نمای کلی</b></span>`;document.querySelector('#menu').onclick=()=>document.querySelector('#sidebar').classList.toggle('open');
document.querySelector('#agent-launcher').innerHTML=icon('spark')+'<span>همراه هشتیوا</span>';document.querySelector('#agent-launcher').setAttribute('title','پیشنهادهای آماده در بخش فعلی');
const button=(text,attrs='',primary=false,ic='')=>`<button class="btn ${primary?'primary':''}" ${attrs}>${ic?icon(ic):''}${text}</button>`;
function titleV3(title,description,action=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${description}</p></div><div class="page-actions">${action}</div></div>`}
function surfaceHead(title,sub='',action=''){return `<div class="surface-head"><div><h2>${title}</h2>${sub?`<small>${sub}</small>`:''}</div>${action}</div>`}
function miniArt(i=0){return `<div class="product-visual product-${i%3}" aria-hidden="true"><svg viewBox="0 0 120 100"><ellipse cx="60" cy="86" rx="36" ry="5" fill="currentColor" opacity=".08"/>${i%3===0?'<path d="M25 39h70v44H25z" fill="#f2e4d0"/><path d="M21 31h78v13H21z" fill="#e5d2b6"/><path d="M55 31h10v52H55z" fill="#8d9c87"/><path d="M60 31C30 32 33 7 47 15c8 5 13 16 13 16zm0 0c30 1 27-24 13-16-8 5-13 16-13 16z" fill="none" stroke="#8d9c87" stroke-width="5"/>':i%3===1?'<rect x="31" y="14" width="60" height="72" rx="4" fill="#456b66"/><path d="M39 14v72" stroke="#244a47" stroke-width="2"/><rect x="49" y="29" width="30" height="25" rx="1" fill="#d8d9b6"/><path d="M54 36h20m-20 6h15m-15 6h18" stroke="#8a9d88"/>':'<path d="M78 36h10c23 0 19 33-8 30" stroke="#b87e58" stroke-width="9" fill="none"/><path d="M26 29h56v40c0 23-56 23-56 0z" fill="#d4a27e"/><ellipse cx="54" cy="29" rx="28" ry="8" fill="#eac8a9"/><ellipse cx="54" cy="29" rx="22" ry="5" fill="#5d4233"/>'}</svg></div>`}
function dailyPosts(){return posts.slice(0,3).map((p,i)=>`<div class="queue-row">${miniArt(i)}<div class="queue-info"><b>${safe(p.title)}</b><small>${safe(p.kind)} · ${socialNames[p.network||'instagram']}</small></div><span class="tag ${p.draft?'neutral':'blue'}">${p.draft?'پیش‌نویس':'آماده بازبینی'}</span><button class="more-button" data-edit-post="${i}" aria-label="بازبینی ${safe(p.title)}">${icon('arrow')}</button></div>`).join('')}
function dashboardV3(){const date=new Intl.DateTimeFormat('fa-IR',{weekday:'long',day:'numeric',month:'long',year:'numeric'}).format(new Date());return titleV3('امروز در هشتیوا',date,button('ساخت محتوا','data-action="post"',true,'plus'))+`<div class="channel-summary"><span class="summary-label">حساب‌های فضای کار</span><div>${accounts.slice(0,4).map(a=>`<button data-page="channels" class="account-chip">${social(a.network)}<span dir="auto">${safe(a.name)}</span></button>`).join('')}</div><button class="text-link" data-page="channels">مدیریت حساب‌ها ${icon('arrow')}</button></div><div class="overview-metrics">${[['گفتگوی باز',fa(messagesState.filter(m=>m.state!=='done').length),'نیازمند پاسخ یا پیگیری','inbox','amber'],['محتوای آماده',fa(posts.filter(p=>!p.draft).length),'در صف بازبینی تیم','camera','blue'],['جریان فعال',fa(flows.filter(f=>f.active).length),'از '+fa(flows.length)+' جریان نمونه','flow','teal'],['سفارش جدید',fa(orders.filter(o=>o.state==='در انتظار بررسی').length),'در انتظار بررسی','box','violet']].map(x=>`<div class="overview-metric"><div><span>${x[0]}</span><b>${x[1]}</b><small>${x[2]}</small></div><span class="metric-symbol ${x[4]}">${icon(x[3])}</span></div>`).join('')}</div><div class="dashboard-columns"><div class="main-column"><section class="surface">${surfaceHead('میز پیگیری','کارهایی که به تصمیم شما نیاز دارند',`<span class="tag neutral">امروز</span>`)}<div class="task-line"><span class="task-dot amber"></span><div><b>پاسخ به سؤال‌های مشتریان</b><small>${fa(messagesState.filter(m=>m.state!=='done').length)} گفتگوی نمونه هنوز بسته نشده است</small></div>${button('مشاهده گفتگوها','data-page="inbox"',false,'arrow')}</div><div class="task-line"><span class="task-dot blue"></span><div><b>بازبینی محتوای آماده انتشار</b><small>متن، شبکه مقصد و زمان انتشار را بررسی کنید</small></div>${button('بازبینی محتوا','data-page="studio"',false,'arrow')}</div><div class="task-line"><span class="task-dot violet"></span><div><b>تکمیل اطلاعات دستیار</b><small>${fa(knowledge.length)} منبع دانش برای پاسخ‌گویی ثبت شده است</small></div>${button('آموزش دستیار','data-page="knowledge"',false,'arrow')}</div></section><section class="surface">${surfaceHead('صف محتوای شما','از پیش‌نویس تا آماده‌سازی برای انتشار',`<button class="text-link" data-page="studio">همه محتواها ←</button>`)}${dailyPosts()}</section><section class="surface compact-chart">${surfaceHead('عملکرد شبکه‌ها','روند نمونه بازدید و تعامل',`<button class="text-link" data-page="analytics">گزارش کامل ←</button>`)}${chart().replaceAll('data-period','data-dashboard-period')}</section></div><div class="support-column"><section class="agent-overview"><div class="agent-brand">${icon('spark')}<span>HASHTIVA COPILOT</span></div><h2>دستیار شما،<br>در جریان کار شما.</h2><p>منابع برند را کامل کنید تا مسیر پاسخ‌گویی مشخص باشد.</p><div class="agent-setup"><span>منابع دانش</span><b>${fa(knowledge.length)} منبع</b></div><div class="progress-track"><i style="width:${Math.min(knowledge.length*20,100)}%"></i></div><button data-page="knowledge">تنظیم دستیار ${icon('arrow')}</button><small>محیط نمایشی · بدون مدل زنده</small></section><section class="surface idea-brief">${surfaceHead('پیشنهاد برای قدم بعدی','برنامه رشد پیشنهادی')}<span class="idea-label">محتوا از دل گفتگو</span><h3>یک سؤال پرتکرار را به محتوای بعدی تبدیل کنید.</h3><p>سؤال‌های مشتریان درباره انتخاب محصول، نقطه شروع مناسبی برای محتوای آموزشی‌اند.</p><button class="btn" data-use-idea="0">ساخت پیش‌نویس ${icon('plus')}</button></section><section class="surface">${surfaceHead('فعالیت فضای کار')}<div class="activity-item"><i></i><div><b>اطلاعات برند آماده بررسی است</b><small>منابع دستیار · نمونه</small></div></div><div class="activity-item"><i></i><div><b>تقویم محتوایی در دسترس است</b><small>محتوا و انتشار</small></div></div><div class="activity-item"><i></i><div><b>حساب‌های اجتماعی اضافه شده‌اند</b><small>${fa(accounts.length)} حساب نمونه</small></div></div></section></div></div>`}
function inboxV3(){const c=messagesState[selectedInbox];const list=messagesState.map((m,i)=>({m,i})).filter(({m})=>inboxFilter==='all'||m.state===inboxFilter);return titleV3('صندوق گفتگو','گفتگوها را ببینید، پاسخ را بررسی کنید و مسئول پیگیری را مشخص کنید.',`<span class="tag neutral">گفتگوهای نمونه</span>`)+`<div class="inbox-workspace"><section class="thread-list"><div class="thread-tools"><b>همه گفتگوها</b><span>${fa(list.length)}</span></div><div class="thread-filters">${[['all','همه'],['open','باز'],['human','ارجاع'],['done','بسته']].map(([v,t])=>`<button class="${inboxFilter===v?'chosen':''}" data-inbox-filter="${v}">${t}</button>`).join('')}</div>${list.map(({m,i})=>`<button class="thread ${i===selectedInbox?'selected':''}" data-thread="${i}"><span class="person-avatar avatar-${i}">${m.name[0]}${social(m.network)}</span><div><b>${m.name}</b><small>${m.subject}</small><p>${m.text}</p></div><time>${m.time}</time></button>`).join('')||'<div class="empty">گفتگویی در این وضعیت نیست.</div>'}</section><section class="conversation-area"><div class="conversation-top"><span class="person-avatar avatar-${selectedInbox}">${c.name[0]}</span><div><b>${c.name}</b><small>${socialNames[c.network]} · ${c.tag}</small></div><button class="btn" data-resolve>${c.state==='done'?'بازگشایی':'بستن گفتگو'} ${icon('check')}</button></div><div class="conversation-scroll"><span class="conversation-date">گفتگوی نمونه · امروز</span><div class="incoming-message">${c.text}<small>${c.time}</small></div>${c.replies.map(t=>`<div class="outgoing-message">${safe(t)}<small>ثبت در پیش‌نمایش</small></div>`).join('')}<div class="draft-assistance"><div>${icon('spark')}<b>پاسخ پیشنهادی</b><span>آماده</span></div><p>${safe(replyFor(c))}</p><button class="text-link" data-insert-reply>قرار دادن در کادر پاسخ ←</button></div></div><form id="inbox-compose"><textarea name="reply" placeholder="پاسخ خود را بنویسید…" aria-label="متن پاسخ" required></textarea><div><small>پاسخ فقط در این پیش‌نمایش ثبت می‌شود.</small><button class="btn primary">ثبت پاسخ ${icon('arrow')}</button></div></form></section><aside class="customer-info"><h3>اطلاعات مخاطب</h3><span class="person-avatar large avatar-${selectedInbox}">${c.name[0]}</span><b>${c.name}</b><small>مخاطب نمونه</small><dl><dt>کانال</dt><dd>${social(c.network)}${socialNames[c.network]}</dd><dt>موضوع</dt><dd>${c.tag}</dd><dt>وضعیت پیگیری</dt><dd>${c.state==='done'?'بسته‌شده':c.state==='human'?'ارجاع به تیم':'باز'}</dd></dl><label>مسئول پاسخ‌گویی</label><select id="assignee"><option value="open" ${c.state!=='human'?'selected':''}>مدیر فضای کار</option><option value="human" ${c.state==='human'?'selected':''}>تیم پشتیبانی</option></select><button class="btn" data-page="sales">مشاهده سفارش‌ها</button><div class="customer-note">${icon('spark')}<p>پیش از پاسخ، اطلاعات محصول و شرایط ارسال را بررسی کنید.</p></div></aside></div>`}
function replyFor(c){return c.network==='instagram'?'سلام سارا جان، بله؛ بسته‌بندی هدیه برای محصولات منتخب در دسترس است. بفرمایید کدام محصول را مدنظر دارید تا دقیق‌تر راهنمایی کنیم.':c.network==='whatsapp'?'سلام، خوشحال می‌شویم پیگیری کنیم. لطفاً شماره سفارش را بفرستید تا وضعیت ارسال را بررسی کنیم.':'سلام، ممنون از علاقه‌مندی شما به همکاری. لطفاً زمینه فعالیت و پیشنهادتان را بفرستید تا تیم بررسی کند.'}
function studioV3(){const filtered=posts.map((p,i)=>({p,i})).filter(({p})=>postFilter==='all'||(postFilter==='draft'?p.draft:!p.draft));return titleV3('محتوا و انتشار','محتوا را برای هر شبکه آماده کنید و با بازبینی تیم جلو ببرید.',button('محتوای جدید','data-action="post"',true,'plus'))+`<div class="section-toolbar"><div class="plain-tabs">${[['all','همه محتواها'],['draft','پیش‌نویس'],['ready','آماده بازبینی']].map(([v,t])=>`<button class="${postFilter===v?'chosen':''}" data-content-filter="${v}">${t}</button>`).join('')}</div><button class="btn" data-page="calendar">${icon('calendar')} نمای تقویم</button></div><div class="publication-grid">${filtered.map(({p,i})=>`<article class="publication-card">${miniArt(i)}<div class="publication-top">${social(p.network||'instagram')}<span class="tag ${p.draft?'neutral':'blue'}">${p.draft?'پیش‌نویس':'آماده بازبینی'}</span></div><h3>${safe(p.title)}</h3><p>${safe(p.caption||'متن محتوا را بازبینی و متناسب با شبکه مقصد تکمیل کنید.')}</p><div class="publication-footer"><small>${safe(p.kind)} · ${safe(p.time)}</small><button data-edit-post="${i}" aria-label="ویرایش محتوا">${icon('arrow')}</button></div></article>`).join('')||'<div class="empty">محتوایی در این وضعیت ندارید.</div>'}</div>`}
function automationsV3(){return titleV3('جریان‌های خودکار','محرک، پاسخ و زمان ارجاع به تیم را در یک مسیر مشخص تعریف کنید.',button('جریان جدید','data-new-flow',true,'plus'))+`<div class="automation-intro"><span>${icon('flow')}</span><div><b>یک مسیر روشن برای هر درخواست</b><p>از کلمه کلیدی تا پاسخ پیشنهادی؛ هر جریان قبل از استفاده قابل بازبینی است.</p></div></div><div class="flow-list">${flows.map((f,i)=>`<article class="surface flow-card"><div class="flow-card-top"><span class="flow-symbol">${icon('flow')}</span><div><h3>${safe(f.title)}</h3><small>دایرکت و پیام · سناریوی نمونه</small></div><button class="v3-toggle ${f.active?'on':''}" data-toggle-flow="${i}" role="switch" aria-checked="${f.active}" aria-label="فعال‌سازی ${safe(f.title)}"></button></div><div class="flow-route"><span><small>وقتی پیام شامل باشد</small><b>${safe(f.trigger)}</b></span><i>←</i><span><small>پاسخ پیشنهادی</small><b>ارسال متن مشخص</b></span><i>←</i><span><small>در صورت ابهام</small><b>ارجاع به تیم</b></span></div><div class="flow-card-footer"><span class="tag ${f.active?'green':'neutral'}">${f.active?'فعال در پیش‌نمایش':'متوقف'}</span><button class="text-link" data-edit-flow="${i}">ویرایش و آزمایش ←</button></div></article>`).join('')}</div>`}
function flowEditor(i){const f=i<0?{title:'',trigger:'',text:''}:flows[i];modal(`<h2>${i<0?'جریان جدید':'ویرایش جریان'}</h2><small>سناریو در همین مرورگر ذخیره می‌شود.</small><form id="flow-form" data-index="${i}"><label>نام جریان</label><input name="title" required value="${safe(f.title)}"><label>کلمه کلیدی</label><input name="trigger" required value="${safe(f.trigger)}" placeholder="مثلاً قیمت"><label>پاسخ پیشنهادی</label><textarea name="text" required>${safe(f.text)}</textarea><div class="flow-preview"><small>پیش‌نمایش پیام</small><p id="flow-preview-text">${safe(f.text)||'متن پاسخ شما اینجا نمایش داده می‌شود.'}</p></div><p><button class="btn primary">ذخیره جریان</button></p></form>`)}
function knowledgeV3(){return titleV3('آموزش دستیار برند','اطلاعات معتبر، لحن پاسخ و مرز مسئولیت دستیار را تعیین کنید.',button('افزودن منبع','data-new-knowledge',true,'plus'))+`<div class="knowledge-layout"><section class="surface">${surfaceHead('پایگاه دانش',fa(knowledge.length)+' منبع متنی ثبت‌شده')}<div class="knowledge-list">${knowledge.map((k,i)=>`<div class="knowledge-row"><span>${icon('book')}</span><div><b>${safe(k.title)}</b><p>${safe(k.text)}</p></div><button class="text-link" data-edit-knowledge="${i}">ویرایش</button></div>`).join('')||'<div class="empty">اولین منبع را اضافه کنید.</div>'}</div><div class="knowledge-hint">${icon('spark')}<p>اطلاعات محصول، زمان ارسال و سیاست بازگشت را به‌صورت جداگانه ثبت کنید.</p></div></section><section class="surface">${surfaceHead('رفتار دستیار','پیکربندی نمایشی')}<form id="agent-policy"><label>لحن پاسخ</label><select name="tone"><option>صمیمی و حرفه‌ای</option><option>رسمی و کوتاه</option><option>راهنما و آموزشی</option></select><label>در صورت نبود اطلاعات</label><select name="fallback"><option>ارجاع به تیم پشتیبانی</option><option>درخواست توضیح بیشتر</option></select><label class="policy-check"><input type="checkbox" name="review" ${localStorage.getItem('ht-review')!=='false'?'checked':''}>پاسخ‌ها پیش از ارسال نیاز به تأیید دارند</label><button class="btn primary">ذخیره تنظیمات</button></form><div class="policy-note">هیچ مدل هوش مصنوعی به این نسخه متصل نیست. منابع و تنظیمات برای نمایش جریان محصول ذخیره می‌شوند.</div></section></div>`}
function knowledgeEditor(i){const k=i<0?{title:'',text:''}:knowledge[i];modal(`<h2>${i<0?'افزودن منبع دانش':'ویرایش منبع'}</h2><form id="knowledge-form" data-index="${i}"><label>عنوان</label><input name="title" required value="${safe(k.title)}"><label>اطلاعات قابل استناد برای دستیار</label><textarea name="text" required>${safe(k.text)}</textarea><p><button class="btn primary">ذخیره منبع</button></p></form>`)}
function salesV3(){return titleV3('محصولات و سفارش‌ها','مسیر گفتگو تا سفارش را در یک فضای کاری پیگیری کنید.',button('محصول جدید','data-new-product',true,'plus'))+`<div class="section-toolbar"><div class="plain-tabs"><button data-sales-tab="orders" class="${salesTab==='orders'?'chosen':''}">سفارش‌ها <span>${fa(orders.length)}</span></button><button data-sales-tab="products" class="${salesTab==='products'?'chosen':''}">محصولات <span>${fa(products.length)}</span></button></div><span class="muted">اطلاعات نمونه · تومان</span></div>${salesTab==='orders'?`<section class="surface table-surface"><div class="table-wrap"><table><thead><tr><th>شماره سفارش</th><th>مشتری / کانال</th><th>محصول</th><th>مبلغ</th><th>وضعیت</th><th></th></tr></thead><tbody>${orders.map((o,i)=>`<tr><td>#${fa(o.id)}</td><td><span class="table-person">${social(o.network)}${o.name}</span></td><td>${o.product}</td><td>${o.value}</td><td><span class="tag ${o.state==='در انتظار بررسی'?'amber':o.state==='ارسال شده'?'green':'blue'}">${o.state}</span></td><td><button class="text-link" data-order="${i}">بررسی ←</button></td></tr>`).join('')}</tbody></table></div></section>`:`<div class="publication-grid">${products.map((p,i)=>`<article class="publication-card">${miniArt(i)}<h3>${safe(p.name)}</h3><div class="product-details"><b>${safe(p.price)} <small>تومان</small></b><span class="tag green">${fa(p.stock)} موجود</span></div></article>`).join('')}</div>`}`}
function growthV3(){return titleV3('فرصت‌های رشد','هر پیشنهاد، یک اقدام مشخص و یک معیار برای بررسی نتیجه.',button('گفتگو با همراه','data-agent="context"',false,'spark'))+`<div class="growth-summary"><div><span class="tag blue">پیشنهادهای آماده</span><h2>این هفته، روی یک هدف تمرکز کنید.</h2><p>یک آزمایش کوچک انتخاب کنید، محتوایش را بسازید و نتیجه را ثبت کنید.</p></div><div class="growth-steps"><span>۱ <b>انتخاب فرضیه</b></span><i>←</i><span>۲ <b>اجرای محتوا</b></span><i>←</i><span>۳ <b>بررسی نتیجه</b></span></div></div><div class="growth-grid">${growthIdeas.map((g,i)=>`<article class="surface opportunity"><div class="opportunity-top"><span class="opportunity-index">${fa(i+1).padStart(2,'۰')}</span><span class="tag neutral">${g[0]}</span><button class="bookmark" data-save-idea="${i}" aria-label="ذخیره ایده">${ideasSaved.includes(i)?'★':'☆'}</button></div><h3>${g[1]}</h3><p>${g[2]}</p><div class="opportunity-measure"><small>معیار بررسی</small><b>${g[3]}</b></div><div class="opportunity-action"><button class="btn" data-use-idea="${i}">ساخت پیش‌نویس ${icon('arrow')}</button><span>اجرای پیشنهادی: این هفته</span></div></article>`).join('')}</div>`}
const previousWorkspaceRender=render;
render=function(page='dashboard'){previousWorkspaceRender(page);current=Object.hasOwn(titles,page)?page:'dashboard';if(current==='dashboard')main.innerHTML=dashboardV3();if(current==='studio')main.innerHTML=studioV3();if(current==='inbox')main.innerHTML=inboxV3();if(current==='automations')main.innerHTML=automationsV3();if(current==='knowledge')main.innerHTML=knowledgeV3();if(current==='sales')main.innerHTML=salesV3();if(current==='growth')main.innerHTML=growthV3();document.querySelector('#crumb').textContent=titles[current];document.title='هشتیوا | '+titles[current];navV3();document.querySelector('#sidebar').classList.remove('open');updateAgentHeader();document.querySelectorAll('.copilot-strip').forEach(x=>x.remove());if(current==='knowledge'){const f=main.querySelector('#agent-policy');f.elements.tone.value=localStorage.getItem('ht-policy-tone')||'صمیمی و حرفه‌ای';f.elements.fallback.value=localStorage.getItem('ht-policy-fallback')||'ارجاع به تیم پشتیبانی'}};
function openOrder(i){const o=orders[i];modal(`<h2>سفارش #${fa(o.id)}</h2><div class="order-summary"><span>${o.name}</span><b>${o.product}</b><p>${o.value} تومان</p></div><form id="order-form" data-index="${i}"><label>وضعیت سفارش</label><select name="state">${['در انتظار بررسی','آماده ارسال','ارسال شده'].map(s=>`<option ${o.state===s?'selected':''}>${s}</option>`).join('')}</select><p><button class="btn primary">ثبت وضعیت نمونه</button></p><small>هیچ پرداخت یا ارسال واقعی انجام نمی‌شود.</small></form>`)}
document.addEventListener('click',e=>{let t=e.target.closest('[data-thread]');if(t){selectedInbox=+t.dataset.thread;render('inbox')}t=e.target.closest('[data-inbox-filter]');if(t){inboxFilter=t.dataset.inboxFilter;render('inbox')}if(e.target.closest('[data-insert-reply]')){document.querySelector('#inbox-compose textarea').value=replyFor(messagesState[selectedInbox]);document.querySelector('#inbox-compose textarea').focus()}if(e.target.closest('[data-resolve]')){let m=messagesState[selectedInbox];m.state=m.state==='done'?'open':'done';saveV3();render('inbox')}t=e.target.closest('[data-content-filter]');if(t){postFilter=t.dataset.contentFilter;render('studio')}if(e.target.closest('[data-new-flow]'))flowEditor(-1);t=e.target.closest('[data-edit-flow]');if(t)flowEditor(+t.dataset.editFlow);t=e.target.closest('[data-toggle-flow]');if(t){flows[+t.dataset.toggleFlow].active=!flows[+t.dataset.toggleFlow].active;saveV3();render('automations')}if(e.target.closest('[data-new-knowledge]'))knowledgeEditor(-1);t=e.target.closest('[data-edit-knowledge]');if(t)knowledgeEditor(+t.dataset.editKnowledge);t=e.target.closest('[data-sales-tab]');if(t){salesTab=t.dataset.salesTab;render('sales')}t=e.target.closest('[data-order]');if(t)openOrder(+t.dataset.order);if(e.target.closest('[data-new-product]'))modal('<h2>محصول جدید</h2><form id="product-form"><label>نام محصول</label><input name="name" required maxlength="80"><label>قیمت به تومان</label><input name="price" type="number" min="0" required><label>موجودی</label><input name="stock" type="number" min="0" value="1" required><p><button class="btn primary">ثبت محصول نمونه</button></p></form>')});
document.addEventListener('change',e=>{if(e.target.id==='assignee'){messagesState[selectedInbox].state=e.target.value;saveV3();render('inbox')}});document.addEventListener('input',e=>{if(e.target.name==='text'&&e.target.closest('#flow-form'))document.querySelector('#flow-preview-text').textContent=e.target.value});
document.addEventListener('submit',e=>{const f=new FormData(e.target),id=e.target.id;const index=Number(e.target.dataset.index);if(id==='inbox-compose'){const text=f.get('reply').trim();if(text){messagesState[selectedInbox].replies.push(text);saveV3();render('inbox');toast('پاسخ در پیش‌نمایش ثبت شد')}}if(id==='flow-form'){const entry={title:f.get('title'),trigger:f.get('trigger'),text:f.get('text'),active:index<0?false:flows[index].active};if(index<0)flows.push(entry);else flows[index]=entry;saveV3();dialog.close();render('automations');toast('جریان ذخیره شد')}if(id==='knowledge-form'){const entry={title:f.get('title'),text:f.get('text')};if(index<0)knowledge.push(entry);else knowledge[index]=entry;saveV3();dialog.close();render('knowledge')}if(id==='agent-policy'){localStorage.setItem('ht-policy-tone',f.get('tone'));localStorage.setItem('ht-policy-fallback',f.get('fallback'));localStorage.setItem('ht-review',String(f.get('review')==='on'));toast('رفتار دستیار ذخیره شد')}if(id==='order-form'){orders[index].state=f.get('state');saveV3();dialog.close();render('sales')}if(id==='product-form'){products.push({name:f.get('name'),price:fa(f.get('price')),stock:Number(f.get('stock'))});saveV3();dialog.close();salesTab='products';render('sales')}});
// No simulated live status: the global label explains the demo once.
document.querySelector('.demo').textContent='محیط نمایشی';document.querySelector('footer').innerHTML='<span>هشتیوا · فضای یکپارچه مدیریت شبکه‌های اجتماعی</span><span>داده‌های نمونه · بدون اتصال خارجی</span>';render(location.hash.slice(1)||'dashboard');
calendarPage=function(){let base=new Date();base.setHours(0,0,0,0);base.setDate(base.getDate()+scheduleOffset*7);const dateKey=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;const dates=Array.from({length:7},(_,i)=>{let d=new Date(base);d.setDate(d.getDate()+i);return d});return titleV3('تقویم انتشار','هر محتوا در تاریخ انتخاب‌شده نمایش داده می‌شود؛ انتشار خارجی فعال نیست.',button('محتوای جدید','data-action="post"',true,'plus'))+`<div class="section-toolbar">${button('هفته قبل','data-week="-1"')}<b>${new Intl.DateTimeFormat('fa-IR',{day:'numeric',month:'long',year:'numeric'}).format(base)}</b>${button('هفته بعد','data-week="1"')}<button class="text-link" data-week="0">امروز</button></div><div class="calendar-grid">${dates.map(d=>`<section class="day-column"><div class="day-title"><small>${new Intl.DateTimeFormat('fa-IR',{weekday:'long'}).format(d)}</small><b>${new Intl.DateTimeFormat('fa-IR',{day:'numeric'}).format(d)}</b></div>${posts.map((p,i)=>({p,i})).filter(({p})=>p.due?.slice(0,10)===dateKey(d)).map(({p,i})=>`<button class="calendar-post" data-edit-post="${i}">${social(p.network||'instagram')}<b>${safe(p.title)}</b><small>${new Intl.DateTimeFormat('fa-IR',{hour:'2-digit',minute:'2-digit'}).format(new Date(p.due))}</small><span>برنامه‌ریزی محلی</span></button>`).join('')}<button class="day-add" data-action="post" data-calendar-date="${dateKey(d)}" aria-label="افزودن محتوا در این روز">+</button></section>`).join('')}</div><section class="surface unscheduled"><div class="surface-head"><div><h2>بدون تاریخ انتشار</h2><small>برای نمایش در تقویم، تاریخ را در بازبینی محتوا تعیین کنید.</small></div><span class="tag neutral">${fa(posts.filter(p=>!p.due).length)} محتوا</span></div>${posts.map((p,i)=>({p,i})).filter(({p})=>!p.due).map(({p,i})=>`<div class="queue-row">${miniArt(i)}<div class="queue-info"><b>${safe(p.title)}</b><small>تاریخ مشخص نشده</small></div><button class="text-link" data-edit-post="${i}">تنظیم تاریخ ←</button></div>`).join('')||'<small>همه محتواها تاریخ دارند.</small>'}</section>`};
document.addEventListener('click',e=>{let t=e.target.closest('[data-dashboard-period]');if(t){period=t.dataset.dashboardPeriod;render('dashboard')}t=e.target.closest('[data-calendar-date]');if(t){document.querySelector('#post-form [name="time"]').value=t.dataset.calendarDate+'T18:00'}t=e.target.closest('[data-edit-post]');if(t){const p=posts[+t.dataset.editPost];document.querySelector('#edit-post-form').insertAdjacentHTML('beforeend',`<label>تاریخ و ساعت برنامه‌ریزی</label><input name="due" type="datetime-local" value="${safe(p.due||'')}">`)}});
document.addEventListener('submit',e=>{if(e.target.id==='post-form'){posts[0].due=new FormData(e.target).get('time')||'';persistPosts();render(current)}if(e.target.id==='edit-post-form'){const p=posts[+e.target.dataset.index];p.due=new FormData(e.target).get('due')||'';if(p.due)p.time=new Intl.DateTimeFormat('fa-IR',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}).format(new Date(p.due));persistPosts();render(current)}});
render(location.hash.slice(1)||'dashboard');
